-- Schema of database 'hh_inventory' (PostgreSQL 16), generated by Hibernate from the JPA entities.
-- Reference only: the services create/update these tables automatically (spring.jpa.hibernate.ddl-auto=update).

CREATE TABLE public.medicines (
    id bigint NOT NULL,
    created_at timestamp(6) without time zone,
    updated_at timestamp(6) without time zone,
    category character varying(20) NOT NULL,
    code character varying(20),
    default_reorder_level integer,
    description character varying(500),
    essential boolean,
    form character varying(15),
    generic_name character varying(255),
    manufacturer character varying(255),
    name character varying(255) NOT NULL,
    strength character varying(255),
    unit character varying(255),
    CONSTRAINT medicines_category_check CHECK (((category)::text = ANY ((ARRAY['MEDICINE'::character varying, 'VACCINE'::character varying, 'SUPPLY'::character varying, 'EQUIPMENT'::character varying, 'CONSUMABLE'::character varying, 'DIAGNOSTIC_KIT'::character varying])::text[]))),
    CONSTRAINT medicines_form_check CHECK (((form)::text = ANY ((ARRAY['TABLET'::character varying, 'CAPSULE'::character varying, 'SYRUP'::character varying, 'INJECTION'::character varying, 'OINTMENT'::character varying, 'DROPS'::character varying, 'SACHET'::character varying, 'VIAL'::character varying, 'UNIT'::character varying, 'KIT'::character varying])::text[])))
);
ALTER TABLE public.medicines ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.medicines_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);
CREATE TABLE public.replenishment_requests (
    id bigint NOT NULL,
    created_at timestamp(6) without time zone,
    updated_at timestamp(6) without time zone,
    approved_by character varying(255),
    assigned_to character varying(255),
    current_stock integer,
    fulfilled_date date,
    health_centre_id bigint NOT NULL,
    health_centre_name character varying(255),
    medicine_id bigint NOT NULL,
    medicine_name character varying(255),
    notes character varying(500),
    priority character varying(10),
    reason character varying(500),
    request_number character varying(20),
    requested_by character varying(255),
    requested_quantity integer NOT NULL,
    required_by date,
    source character varying(20),
    status character varying(15),
    CONSTRAINT replenishment_requests_priority_check CHECK (((priority)::text = ANY ((ARRAY['LOW'::character varying, 'MEDIUM'::character varying, 'HIGH'::character varying, 'CRITICAL'::character varying])::text[]))),
    CONSTRAINT replenishment_requests_requested_quantity_check CHECK ((requested_quantity >= 1)),
    CONSTRAINT replenishment_requests_source_check CHECK (((source)::text = ANY ((ARRAY['MANUAL'::character varying, 'AUTO_LOW_STOCK'::character varying, 'FIELD_REPORT'::character varying])::text[]))),
    CONSTRAINT replenishment_requests_status_check CHECK (((status)::text = ANY ((ARRAY['PENDING'::character varying, 'APPROVED'::character varying, 'ORDERED'::character varying, 'FULFILLED'::character varying, 'REJECTED'::character varying])::text[])))
);
ALTER TABLE public.replenishment_requests ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.replenishment_requests_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);
CREATE TABLE public.stock_items (
    id bigint NOT NULL,
    created_at timestamp(6) without time zone,
    updated_at timestamp(6) without time zone,
    batch_number character varying(255),
    category character varying(255),
    expiry_date date,
    health_centre_id bigint NOT NULL,
    health_centre_name character varying(255) NOT NULL,
    last_restocked_date date,
    medicine_id bigint NOT NULL,
    medicine_name character varying(255),
    quantity integer NOT NULL,
    reorder_level integer,
    storage_location character varying(255),
    unit_price double precision,
    CONSTRAINT stock_items_quantity_check CHECK ((quantity >= 0)),
    CONSTRAINT stock_items_reorder_level_check CHECK ((reorder_level >= 0))
);
ALTER TABLE public.stock_items ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.stock_items_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);
CREATE TABLE public.stock_transactions (
    id bigint NOT NULL,
    created_at timestamp(6) without time zone,
    updated_at timestamp(6) without time zone,
    balance_after integer,
    health_centre_id bigint,
    health_centre_name character varying(255),
    issued_to character varying(255),
    medicine_id bigint,
    medicine_name character varying(255),
    notes character varying(500),
    performed_by character varying(255),
    quantity integer,
    reference character varying(255),
    resident_id bigint,
    stock_item_id bigint,
    transaction_date timestamp(6) without time zone,
    type character varying(20),
    CONSTRAINT stock_transactions_type_check CHECK (((type)::text = ANY ((ARRAY['RECEIPT'::character varying, 'ISSUE'::character varying, 'ADJUSTMENT'::character varying, 'EXPIRED_WRITE_OFF'::character varying, 'TRANSFER_OUT'::character varying])::text[])))
);
ALTER TABLE public.stock_transactions ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.stock_transactions_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);
